interface Castable {
    String name();  // abstract — must implement

    default void announce() {
        System.out.println("Preparing: " + name());
    }
}

class Fireball implements Castable {
    public String name() { return "Fireball"; }
    // announce() inherited from interface
}

new Fireball().announce(); // Preparing: Fireball

