public class Main {
    interface Spell {
        String name();
        default String describe() {
            return "Spell: " + name();
        }
    }
    static class IceShot implements Spell {
        public String name() { return "IceShot"; }
        public String describe() { return "Ice: " + name(); }
    }
    static class Arc implements Spell {
        public String name() { return "Arc"; }
    }
    public static void main(String[] args) {
        System.out.println(new IceShot().describe());
        System.out.println(new Arc().describe());
    }
}

public class Main {
    interface Greetable {
        default String greet() { return "Hello!"; }
    }
    interface Farewell {
        default String greet() { return "Goodbye!"; }
    }
    static class Wizard implements Greetable, Farewell {
        // no override
    }
    public static void main(String[] args) {
        System.out.println(new Wizard().greet());
    }
}

