abstract class Spell {
    private final String name;
    Spell(String name) { this.name = name; }
    String getName() { return name; }
    abstract int damage(); // subclasses must define
}

abstract class Ritual {
    final void perform() {  // the template — cannot be overridden
        prepare();
        execute();
        cleanup();
    }
    abstract void prepare();
    abstract void execute();
    void cleanup() { System.out.println("Ritual complete."); }
}

