public class Main {
    abstract static class Quest {
        final void begin() {
            start();
            fight();
            end();
        }
        abstract void start();
        abstract void fight();
        void end() { System.out.println("Quest ended."); }
    }
    static class DragonQuest extends Quest {
        void start() { System.out.println("Entering dragon lair."); }
        void fight() { System.out.println("Fighting dragon!"); }
        void end()   { System.out.println("Dragon slain!"); }
    }
    public static void main(String[] args) {
        new DragonQuest().begin();
    }
}

